 //pressure oversampling rate (value from 0 to 7)\n    //2^prs_osr internal pressure measurements per result\n    //A higher value increases precision\n    int16_t prs_osr = 2;\n    //startMeasureBothCont enables background mode\n    //temperature and pressure ar measured automatically\n    //High precision and hgh measure rates at the same time are not available.\n    //Consult Datasheet (or trial and error) for more information\n    int16_t ret = Dps310PressureSensor.startMeasureBothCont(temp_mr, temp_osr, prs_mr, prs_osr);\n    //Use one of the commented lines below instead to measure only temperature or pressure\n    //int16_t ret = Dps310PressureSensor.startMeasureTempCont(temp_mr, temp_osr);\n    //int16_t ret = Dps310PressureSensor.startMeasurePressureCont(prs_mr, prs_osr);\n\n\n    if (ret != 0) {\n        Serial.print("Init FAILED! ret = ");\n        Serial.println(ret);\n    } else {\n        Serial.println("Init complete!");\n    }\n}\n\n\n\nvoid loop() {\n    uint8_t pressureCount = 20;\n    float pressure[pressureCount];\n    uint8_t temperatureCount = 20;\n    float temperature[temperatureCount];\n\n    //This function writes the results of continuous measurements to the arrays given as parameters\n    //The parameters temperatureCount and pressureCount should hold the sizes of the arrays temperature and pressure when the function is called\n    //After the end of the function, temperatureCount and pressureCount hold the numbers of values written to the arrays\n    //Note: The Dps310 cannot save more than 32 results. When its result buffer is full, it won\'t save any new measurement results\n    int16_t ret = Dps310PressureSensor.getContResults(temperature, temperatureCount, pressure, pressureCount);\n\n    if (ret != 0) {\n        Serial.println();\n        Serial.println();\n        Serial.print("FAIL! ret = ");\n        Serial.println(ret);\n    } else {\n        Serial.println();\n        Serial.println();\n        Serial.print(temperatureCount);\n        Serial.println(" temperature values found: ");\n        for (int16_t i = 0; i < temperatureCount; i++) {\n            Serial.print(temperature[i]);\n            Serial.println(" degrees of Celsius");\n        }\n\n        Serial.println();\n        Serial.print(pressureCount);\n        Serial.println(" pressure values found: ");\n        for (int16_t i = 0; i < pressureCount; i++) {\n            Serial.print(pressure[i]);\n            Serial.println(" Pascal");\n        }\n    }\n\n    //Wait some time, so that the Dps310 can refill its buffer\n    delay(10000);\n}\n'})}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"\u6B65\u9AA4 4."})," \u4E0A\u4F20\u4EE3\u7801\u5E76\u6253\u5F00 ",(0,t.jsx)(n.strong,{children:"\u4E32\u53E3\u76D1\u89C6\u5668"})]}),"\n"]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"\u6CE8\u610F\uFF1A"})," \u4E0A\u4F20\u4EE3\u7801\u540E\uFF0C\u5B83\u4E0D\u4F1A\u81EA\u52A8\u6267\u884C\uFF0C\u76F4\u5230\u60A8\u70B9\u51FB Arduino \u7A97\u53E3\u53F3\u4E0A\u89D2\u7684 ",(0,t.jsx)(n.strong,{children:"\u4E32\u53E3\u76D1\u89C6\u5668"}),"\u3002"]}),"\n",(0,t.jsx)("div",{align:"center",children:(0,t.jsx)("img",{src:"https://files.seeedstudio.com/wiki/XIAO_WiFi/pins-8.jpg",alt:"pir",width:600,height:"auto"})}),"\n",(0,t.jsx)(n.p,{children:"\u73B0\u5728\uFF0C\u60A8\u5C06\u5728\u4E32\u53E3\u76D1\u89C6\u5668\u4E0A\u770B\u5230\u6E29\u5EA6\u548C\u538B\u529B\u6570\u636E\u4E00\u4E2A\u63A5\u4E00\u4E2A\u5730\u663E\u793A\uFF0C\u5982\u4E0A\u56FE\u6240\u793A\uFF01"}),"\n",(0,t.jsx)(n.h2,{id:"\u5173\u4E8E-xiao-esp32c3-io-\u5206\u914D\u7684\u6CE8\u610F\u4E8B\u9879",children:"\u5173\u4E8E XIAO ESP32C3 IO \u5206\u914D\u7684\u6CE8\u610F\u4E8B\u9879"}),"\n",(0,t.jsx)(n.h3,{id:"d9",children:"D9"}),"\n",(0,t.jsx)(n.p,{children:"XIAO ESP32C3 \u7684 D9 \u8FDE\u63A5\u5230 ESP32-C3 \u7684 GPIO9 (15)\u3001\u4E0A\u62C9\u7535\u963B (R6) \u548C BOOT \u6309\u94AE\u3002BOOT \u6309\u94AE\uFF08\u4EE5\u53CA RESET \u6309\u